package net.civeira.phylax.feature.template.templatevariable.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.template.templatevariable.domain.TemplateVariable;
import net.civeira.phylax.feature.template.templatevariable.domain.valueobject.TypeVO;

class TypeValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of type of template variable")
  void test_type_value_holder_assign_plain_value() {
    Object holder = new Object();
    TypeValueHolder<Object> value = new TypeValueHolder<>(holder);
    Assertions.assertSame(holder, value.type("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getTypeValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getType().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of type of template variable")
  void test_type_value_holder_assign_value_object() {
    Object holder = new Object();
    TypeValueHolder<Object> value = new TypeValueHolder<>(holder);
    TypeVO vo = TypeVO.from("one");
    Assertions.assertFalse(value.getTypeValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.type(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getTypeValue().orElseThrow());
    Assertions.assertSame(holder, value.type(Optional.empty()));
    Assertions.assertFalse(value.getTypeValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.type(Optional.of(vo)));
    Assertions.assertSame(vo, value.getTypeValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of type of template variable against the original")
  void test_type_value_holder_read() {
    Object holder = new Object();
    TypeValueHolder<Object> value = new TypeValueHolder<>(holder);
    TypeVO vo = TypeVO.from("one");
    TypeVO other = TypeVO.from("one");
    TemplateVariable original = Mockito.mock(TemplateVariable.class);
    Mockito.when(original.getTypeValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readType(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readType(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.type(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readType(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readType(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of type of template variable")
  void test_type_value_holder_unset() {
    Object holder = new Object();
    TypeValueHolder<Object> value = new TypeValueHolder<>(holder);
    TypeVO vo = TypeVO.from("one");
    value.type(vo);
    Assertions.assertSame(holder, value.unsetTypeIfMatches("type_other"));
    Assertions.assertTrue(value.getTypeValue().isPresent(), "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetTypeIfMatches("type"));
    Assertions.assertFalse(value.getTypeValue().isPresent(), "The field name must clear the value");
    value.type(vo);
    Assertions.assertSame(holder, value.unsetType());
    Assertions.assertFalse(value.getTypeValue().isPresent(), "Unset must clear the value");
  }
}
